# -*- coding: utf-8 -*-
"""Local regression tests for the reinstall duplicate-NEVRA fix (RHEL-25005).

These are not part of the upstream patch.  They exercise the same security
invariant as the reference fix using the repository's own test fixtures:

* the negative path reproduces the vulnerability (two available packages
  sharing one NEVRA collapse to a single candidate), and
* the reinstall call-path must hand every candidate to the solver.
"""
from __future__ import absolute_import, unicode_literals

import unittest

from unittest import mock

import dnf.base
import dnf.query
import dnf.selector
import dnf.subject

import tests.support


class PerNevraDictDuplicateTest(unittest.TestCase):
    """Vulnerability-triggering negative path on real mock-sack data."""

    def test_per_nevra_dict_retains_all_duplicate_candidates(self):
        # 'hole-1-2.x86_64' is available in both the 'updates' and the
        # 'third_party' repository, i.e. two packages share one NEVRA.
        sack = tests.support.mock_sack("updates", "third_party")
        pkgs = sack.query().available().filter(name="hole")
        dct = dnf.query._per_nevra_dict(pkgs)

        duplicated = [pkg for pkg in pkgs if str(pkg) == "hole-1-2.x86_64"]
        self.assertEqual(len(duplicated), 2)
        self.assertIn("hole-1-2.x86_64", dct)
        candidates = dct["hole-1-2.x86_64"]
        # The fixed implementation keeps a list of every candidate; the
        # vulnerable implementation keeps only the last one.
        self.assertIsInstance(candidates, list)
        self.assertCountEqual([str(p) for p in candidates],
                              ["hole-1-2.x86_64", "hole-1-2.x86_64"])
        self.assertCountEqual(sorted(p.reponame for p in candidates),
                              ["third_party", "updates"])


