        self.history = None
        self._query = query


class ReinstallAllCandidatesTest(unittest.TestCase):
    """Reinstall must pass every duplicate-NEVRA candidate to the solver."""

    def test_reinstall_offers_all_duplicate_candidates(self):
        installed = _Pkg("hole-1-1.x86_64")
        cand_a = _Pkg("hole-1-1.x86_64")
        cand_b = _Pkg("hole-1-1.x86_64")
        query = _FakeQuery([installed], [cand_a, cand_b])
        base = _FakeBase(query)

        class FakeSubject(object):
            def __init__(self, pkg_spec):
                self.pkg_spec = pkg_spec

            def get_best_query(self, sack):
                return query

        with mock.patch.object(dnf.subject, "Subject", FakeSubject), \
                mock.patch.object(dnf.selector, "Selector", _FakeSelector):
            cnt = dnf.base.Base.reinstall(base, "hole")

        self.assertEqual(cnt, 1)
        self.assertEqual(len(base._goal.calls), 1)
        kind, args, kwargs = base._goal.calls[0]
        self.assertEqual(kind, "install")
        selector = kwargs.get("select")
        self.assertIsInstance(selector, _FakeSelector)
        self.assertCountEqual([str(p) for p in selector.pkgs],
                              ["hole-1-1.x86_64", "hole-1-1.x86_64"])
        # conf.strict is True, so the install must not be optional
        self.assertEqual(kwargs.get("optional"), False)

    def test_reinstall_missing_available_keeps_installed_candidate_count(self):
        # Positive path: NEVRA without an available candidate and remove_na
        # default is False -> installed package is skipped, still counted.
        installed = _Pkg("hole-1-1.x86_64")
        other = _Pkg("other-1-0.x86_64")
        query = _FakeQuery([installed], [other])
        base = _FakeBase(query)

        class FakeSubject(object):
            def __init__(self, pkg_spec):
                self.pkg_spec = pkg_spec

            def get_best_query(self, sack):
                return query

        with mock.patch.object(dnf.subject, "Subject", FakeSubject), \
                mock.patch.object(dnf.selector, "Selector", _FakeSelector):
            cnt = dnf.base.Base.reinstall(base, "hole")

        self.assertEqual(cnt, 1)
        self.assertEqual(base._goal.calls, [])


